<template>
  <div class="CrosshairLayer">
    <div class="header">
      <div class="items">
        <i
          class="fa-duotone fa-align-left handle cursor-pointer duration-300 hover:text-blue-400"
          v-tooltip="'Drag to reorder'"
        ></i>
        <i
          v-if="collapsed"
          class="fa-duotone fa-circle-plus cursor-pointer duration-300 hover:text-green-400"
          @click="collapse"
          v-tooltip="'Extend View'"
        ></i>
        <i
          v-else
          class="fa-duotone fa-circle-minus cursor-pointer duration-300 hover:text-green-400"
          @click="collapse"
          v-tooltip="'Reduce View'"
        ></i>
        <i
          v-if="!setting.hidden"
          @click="toggleHide"
          class="fa-duotone fa-eye cursor-pointer duration-300 hover:text-purple-400"
          v-tooltip="'Hide Layer'"
        ></i>
        <i
          v-else
          @click="toggleHide"
          class="fa-duotone fa-eye-slash cursor-pointer duration-300 hover:text-purple-400"
          v-tooltip="'Show Layer'"
        ></i>
        <i
          class="fa-duotone fa-clone cursor-pointer duration-300 hover:text-yellow-400"
          @click="cloneLayer"
          v-tooltip="'Clone Layer'"
        ></i>
        <div class="title">
          <input
            type="text"
            @focus="toggleTyping(true)"
            @blur="toggleTyping(false)"
            @change="changeLayerName"
            :value="setting.name"
            class="w-40"
            maxlength="15"
            v-tooltip="'Click to edit'"
          />
        </div>
      </div>
      <i
        class="fa-duotone fa-circle-xmark cursor-pointer duration-300 hover:text-red-400"
        @click="$emit('removeLayer', index)"
        v-tooltip="'Delete Layer'"
      ></i>
    </div>
    <div class="configs" v-show="!collapsed">
      <CrossConfig
        v-if="setting.type === 1"
        @updateLayer="$emit('updateLayer', index, $event)"
        :setting="setting"
      />
      <CircleConfig
        v-if="setting.type === 2"
        @updateLayer="$emit('updateLayer', index, $event)"
        :setting="setting"
      />
    </div>
  </div>
</template>

<script>
import CrossConfig from "../../../../../components/Crosshair/Types/Cross/CrossConfig.vue";
import CircleConfig from "../../../../../components/Crosshair/Types/Circle/CircleConfig.vue";
import cloneDeep from "lodash/cloneDeep";

export default {
  components: { CrossConfig, CircleConfig },
  name: "CrosshairLayer",
  emits: ["removeLayer", "updateLayer", "cloneLayer"],
  methods: {
    cloneLayer() {
      this.$emit("cloneLayer", cloneDeep(this.setting));
    },
    toggleTyping(state) {
      if (this.devMode) return;
      // eslint-disable-next-line no-undef
      mp.trigger("MenuToggleTyping", state);
    },
    collapse() {
      this.collapsed = !this.collapsed;
    },
    toggleHide() {
      let newSetting = { ...this.setting };
      newSetting.hidden = !newSetting.hidden;
      this.$emit("updateLayer", this.index, newSetting);
    },
    changeLayerName(event) {
      let newSetting = { ...this.setting };
      newSetting.name = event.target.value;
      this.$emit("updateLayer", this.index, newSetting);
    },
  },
  props: {
    index: {
      type: Number,
    },
    setting: {
      type: Object,
    },
    devMode: {
      type: Boolean,
    },
  },
  data() {
    return {
      collapsed: true,
    };
  },
};
</script>

<style lang="scss" scoped>
::selection {
  color: $blue;
  background: rgba($blue, 0.3);
}

.CrosshairLayer {
  background: lighten($foreground, 5%);
  border-radius: $radius-md;
  padding: 10px;
  border: 1.5px solid lighten($foreground, 15%);
  color: $white-text;
  margin-bottom: 5px;

  .header {
    display: flex;
    justify-content: space-between;
    align-items: center;

    .items {
      display: inline-flex;
      align-items: center;
      justify-content: flex-start;
      gap: 5px;

      .title {
        flex: 1.5;
        input {
          background: transparent;
          padding-left: 5px;
          width: 100%;

          &:focus {
            outline: 2px solid rgba($blue, 0.3);
            border-radius: 5px;
          }
        }
      }

      code {
        //OLD INDEX VIEWER
        background: lighten($background, 5%);
        font-size: 12px;
        padding: 2px 5px;
        border-radius: 5px;
        flex: 1;
      }
    }

    .close {
      height: 15px;
      width: 12px;
      display: flex;
      justify-content: center;
      align-items: center;
      &:hover {
        color: rgb(255, 158, 158);
      }
    }

    .collapse {
      &:hover {
        color: $orange;
      }
    }

    .hide {
      width: 16px;
      display: flex;
      justify-content: center;
      align-items: center;
      &:hover {
        color: lightpink;
      }
    }

    .clone {
      &:hover {
        color: lightgreen;
      }
    }
  }
}
</style>
