<template>
  <div class="flex gap-2">
    <Card class="w-7/12">
      <template #header>
        <div class="flex pr-3">
          <input
            type="text"
            class="bg-transparent w-48"
            :value="getSelectedProfile.label"
            @change="updateLabel"
            maxlength="15"
            v-tooltip="'Click to edit'"
            @focus="toggleTyping(true)"
            @blur="toggleTyping(false)"
          />
          <div class="flex flex-grow items-center justify-end gap-1">
            <i
              class="fa-duotone fa-clone duration-300 hover:text-yellow-400 cursor-pointer"
              @click="createProfile(true)"
              v-tooltip="'Clone Profile'"
            ></i>
            <i
              v-if="profiles.length > 1"
              class="fa-duotone fa-trash-can duration-300 hover:text-red-400 cursor-pointer"
              @click="deleteProfile"
              v-tooltip="'Delete Profile'"
            ></i>
          </div>
        </div>
      </template>
      <CrosshairLayers
        @addLayer="addLayer"
        @updateLayer="updateLayer"
        @removeLayer="removeLayer"
        :layers="selectedProfile.layers"
      />
    </Card>
    <Card class="flex-grow">
      <div
        :style="{ backgroundImage: `url('${crosshairBG}')` }"
        class="w-full h-28 flex justify-center items-center bg-no-repeat crosshair-box"
      >
        <Crosshair h="100px" w="100px" :layers="getSelectedProfile.layers" />
      </div>
      <div class="flex mt-3 mb-3 gap-3">
        <Button v-if="profiles.length < 10" @click="createProfile(false)"
          >New Profile</Button
        >
        <v-select
          placeholder="Select profile"
          class="flex-grow"
          v-model="selectedProfile"
          :options="profiles"
          :clearable="false"
          :searchable="false"
        ></v-select>
      </div>
      <div class="grid">
        <div class="flex flex-col">
          <label for="crosshairEnabled">Crosshair Enabled</label>
          <Toggle id="crosshairEnabled" v-model="crosshair.enabled" />
        </div>
        <div class="flex flex-col">
          <label for="crosshairAlwaysOn">Always On</label>
          <Toggle id="crosshairAlwaysOn" v-model="crosshair.alwaysOn" />
        </div>
        <div class="flex flex-col">
          <label for="crosshairOnSnipers">Enabled On Snipers</label>
          <Toggle id="crosshairOnSnipers" v-model="crosshair.onSinipers" />
        </div>
      </div>
    </Card>
  </div>
</template>

<script>
import Card from "../../../../../components/Card.vue";
import Crosshair from "../../../../../components/Crosshair/Crosshair.vue";
import CrosshairLayers from "./CrosshairLayers.vue";
import Toggle from "@vueform/toggle";
import { v4 as uuidv4 } from "uuid";
import Button from "../../../../../components/Button.vue";
import cloneDeep from "lodash/cloneDeep";

export default {
  name: "CrosshairTab",
  props: ["devMode"],
  components: { Card, Crosshair, CrosshairLayers, Toggle, Button },
  data() {
    return {
      crosshair: {
        enabled: true,
        alwaysOn: false,
        onSinipers: false,
      },
      selectedProfile: {
        label: "Default",
        uuid: 1,
        layers: [],
      },
      crosshairBG: require("@/assets/images/crosshair-maker-background.png"),
      value: 0,
      profiles: [
        {
          label: "Default",
          uuid: 1,
          layers: [],
        },
      ],
    };
  },
  watch: {
    profiles: {
      handler() {
        console.log("Crosshair profiles saved!");
        if (this.devMode) return;
        // eslint-disable-next-line
        mp.trigger("saveCrosshairProfiles", JSON.stringify(profiles));
      },
      deep: true,
    },
  },
  mounted() {
    let firstTime = true;
    const pushLayer = () => {
      let profile = {
        label: `Profile ${this.profiles.length + 1}`,
        uuid: uuidv4(),
        layers: [
          {
            name: "Layer Cross",
            hidden: false,
            sides: [true, true, true, true],
            type: 1,
            gap: "1",
            size: "6.8",
            width: "1",
            rotation: "0",
            radius: "0",
            color: "#e3e3e3a5",
            outline: {
              enable: false,
              width: "1",
              color: "#1f1f1f",
              enabled: false,
            },
            dot: {
              enabled: false,
              size: "3",
              radius: "0",
              color: "#e3e3e3",
            },
            offset: {
              top: "0",
              right: "0",
            },
          },
          {
            name: "Layer Circle",
            hidden: false,
            type: 2,
            width: "2",
            color: "#e3e3e3a0",
            size: {
              separated: false,
              y: "16",
              x: "20",
            },
            rotation: "0",
            fill: {
              enabled: false,
              color: "#e3e3e3",
            },
            outline: {
              enabled: false,
              width: "2",
              color: "#1f1f1f",
            },
            offset: {
              top: "0",
              right: "0",
            },
          },
        ],
      };
      if (firstTime)
        (profile.label = "Profile 1"),
          (this.profiles = [profile]),
          (this.selectedProfile = profile),
          (firstTime = false);
      else this.profiles.push(profile);
    };
    pushLayer();
    pushLayer();
    pushLayer();
  },
  computed: {
    getSelectedProfile() {
      return this.profiles[
        this.profiles.map((p) => p.uuid).indexOf(this.selectedProfile.uuid)
      ];
    },
  },
  methods: {
    toggleTyping(state) {
      if (this.devMode) return;
      // eslint-disable-next-line no-undef
      mp.trigger("MenuToggleTyping", state);
    },
    createProfile(duplicate) {
      if (duplicate) {
        let newProfile = cloneDeep(this.getSelectedProfile);
        newProfile.uuid = uuidv4();
        this.profiles.push(newProfile);
        this.selectedProfile = newProfile;
      } else {
        let profile = {
          label: `Profile ${this.profiles.length + 1}`,
          uuid: uuidv4(),
          layers: [],
        };
        this.profiles.push(profile);
        this.selectedProfile = profile;
      }
    },
    deleteProfile() {
      if (this.profiles.length < 2) return;
      this.profiles.splice(
        this.profiles.map((p) => p.uuid).indexOf(this.selectedProfile.uuid),
        1
      );
      this.selectedProfile = this.profiles[0];
    },
    updateLabel(event) {
      if (event.target.value.length < 1)
        this.getSelectedProfile.label = "Unnamed";
      else this.getSelectedProfile.label = event.target.value;
    },
    updateLayers(newLayers) {
      this.getSelectedProfile.layers = newLayers;
    },
    addLayer(layer) {
      this.getSelectedProfile.layers.push(layer);
    },
    updateLayer(index, layer) {
      this.getSelectedProfile.layers[index] = layer;
    },
    removeLayer(index) {
      this.layers.splice(index, 1);
    },
  },
};
</script>
<style scoped lang="scss">
.crosshair-box {
  border-radius: $radius-md;
}
</style>
