<template>
  <div>
    <label for="color">Color</label>
    <ColorPicker v-model="newSettings.color" />
  </div>
  <div>
    <label>Gap: {{ newSettings.gap }}</label>
    <Slider
      :lazy="false"
      :tooltips="false"
      :step="2"
      :max="159"
      v-model="newSettings.gap"
    />
  </div>
  <div>
    <label>Size: {{ newSettings.size }}</label>
    <Slider
      :lazy="false"
      :tooltips="false"
      v-model="newSettings.size"
      :step="0.1"
      :min="0.1"
      :max="100"
    />
  </div>
  <div>
    <label>Width: {{ newSettings.width }}a2</label>
    <Slider
      :lazy="false"
      :tooltips="false"
      v-model="newSettings.width"
      :step="2"
      :max="99"
    />
  </div>
  <div>
    <label>Radius: {{ newSettings.radius }}</label>
    <Slider
      :lazy="false"
      :tooltips="false"
      v-model="newSettings.radius"
      @input="$emit('updateLayer', this.newSettings)"
      :min="0"
      :max="100"
    />
  </div>
  <div>
    <label>Rotation: {{ newSettings.rotation }}</label>
    <Slider
      :lazy="false"
      :tooltips="false"
      v-model="newSettings.rotation"
      @input="$emit('updateLayer', this.newSettings)"
      :min="0"
      :max="100"
    />
  </div>
  <div>
    <Fieldset title="Sides">
      <div class="sides">
        <div style="width: 50px">
          <label>Top</label>
          <Toggle v-model="newSettings.sides[0]" />
        </div>
        <div style="width: 50px">
          <label>Left</label>
          <Toggle v-model="newSettings.sides[1]" />
        </div>
        <div style="width: 50px">
          <label>Right</label>
          <Toggle v-model="newSettings.sides[2]" />
        </div>
        <div style="width: 50px">
          <label>Bottom</label>
          <Toggle v-model="newSettings.sides[3]" />
        </div>
      </div>
    </Fieldset>
  </div>
  <div>
    <Fieldset title="Dot">
      <div>
        <label>Enable</label>
        <Toggle v-model="newSettings.dot.enabled" />
      </div>
      <div v-show="newSettings.dot.enabled">
        <div>
          <label for="color">Color</label>
          <ColorPicker v-model="newSettings.dot.color" />
        </div>
        <div>
          <label>Size: {{ newSettings.dot.size }}</label>
          <Slider
            :lazy="false"
            :tooltips="false"
            v-model="newSettings.dot.size"
            :step="2"
            :max="99"
          />
        </div>
        <div>
          <label>Radius: {{ newSettings.dot.radius }}</label>
          <Slider
            :lazy="false"
            :tooltips="false"
            v-model="newSettings.dot.radius"
            :max="100"
          />
        </div>
      </div>
    </Fieldset>
  </div>
  <div>
    <Fieldset title="Outline">
      <div>
        <label>Enable</label>
        <Toggle v-model="newSettings.outline.enabled" />
      </div>
      <div v-show="newSettings.outline.enabled">
        <div>
          <label for="color">Color</label>
          <ColorPicker v-model="newSettings.outline.color" />
        </div>
        <div>
          <label>Width: {{ newSettings.outline.width }}</label>
          <Slider
            :lazy="false"
            :tooltips="false"
            v-model="newSettings.outline.width"
            :step="1"
            :min="1"
            :max="5"
          />
        </div>
      </div>
    </Fieldset>
  </div>
  <div>
    <Fieldset title="Offsets">
      <div>
        <label>Top: {{ newSettings.offset.top }}</label>
        <Slider
          :lazy="false"
          :tooltips="false"
          v-model="newSettings.offset.top"
          :min="-150"
          :max="150"
        />
      </div>
      <div>
        <label>Right: {{ newSettings.offset.right }}</label>
        <Slider
          :lazy="false"
          :tooltips="false"
          v-model="newSettings.offset.right"
          :min="-150"
          :max="150"
        />
      </div>
    </Fieldset>
  </div>
</template>

<script>
import Slider from "@vueform/slider";
import ColorPicker from "../../../ColorPicker.vue";
import Fieldset from "../../../Fieldset.vue";
import Toggle from "@vueform/toggle";

export default {
  components: { Slider, ColorPicker, Fieldset, Toggle },
  name: "CrossConfig",
  emits: ["updateLayer"],
  data() {
    return {
      newSettings: {},
      colors: "#194D33A8",
    };
  },
  created() {
    this.newSettings = { ...this.setting };
  },
  watch: {
    newSettings: {
      handler(val) {
        this.$emit("updateLayer", val);
      },
      deep: true,
    },
  },
  props: {
    setting: {
      type: Object,
    },
  },
};
</script>

<style lang="scss" scoped>
.vc-sketch {
  background: darken($gray, 5%);

  input {
    background: red;
  }
}

.sides {
  display: flex;
  flex-direction: row !important;

  div {
    margin: 0 10px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
  }
}

div {
  display: flex;
  flex-direction: column;
  margin: 5px 0;
}

label {
  font-weight: 400;
}
</style>
